## BOJ 문제번호 문제이름
- 문제 카테고리 작성
- https://www.acmicpc.net/problem/16234


## 풀이

해당 문제는 크게 3개의 로직으로 구상을 했습니다.
1. 모든 배열을 순회
2. 방문하지 않은 배열 요소에 대해 bfs수행
3. 수행 후 연합된 국가들간의 결합


### 1. 모든 배열의 순회
 가장 먼저 수행되는 함수로 while문을 돌리면서 더 이상 연합국가의 인구이동이 발생하지 않을 때 까지 반복이 되도록 했습니다.
인구이동은 ``list``라는 객체 list 변수 크기에 따라 boolean 타입의 flag를 변경시키는 절차를 밟도록 했습니다. 

~~~java
 static int open(){
        int result = 0;
        while(true){
            visited = new boolean[n][n];
            boolean flag = false;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if(visited[i][j]) continue;
                    List<Loc> list = bfs(i, j);
                    if(list.size()> 1){
                        setWorld(list);
                        flag = true;
                    }

                }
            }
            if(!flag) return result;
            result ++;

        }
    }
~~~

### 2. 방문하지 않은 배열 요소에 대해 bfs수행
일반적인 bfs에 배열을 벗어나지  않으며, 주어진 조건만큼의 인구차이를 갖고 있는, 마지막으로 방문하지 않은 위치에 대하여 queue에 추가적인 삽입과 list에 추가가 되도록 했습니다.
반환 타입은 list<Loc>으로 각각의 좌표가 담긴 리스트를 반환되도록 했습니다.

~~~java
static List<Loc> bfs(int r, int c){

        Queue<Loc> queue = new LinkedList<>();
        List<Loc> list = new ArrayList<>();
        queue.add(new Loc(r, c));
        list.add(new Loc(r,c));
        tmp = world[r][c];
        visited[r][c] = true;
        while (!queue.isEmpty()){
            Loc loc = queue.poll();
            int pr = loc.r;
            int pc = loc.c;

            for (int i = 0; i < 4; i++) {
                int nr = pr + dr[i];
                int nc = pc + dc[i];
                if(!isCheck(nr, nc) || visited[nr][nc] || !isCheckBound(pr, pc, nr, nc)) continue;
                visited[nr][nc] = true;
                queue.offer(new Loc(nr, nc));
                list.add(new Loc(nr, nc));
                tmp += world[nr][nc];
            }
        }
        return list;
    }

    static boolean isCheck(int nr, int nc){
        return 0<= nr && nr < n && 0 <= nc && nc < n;
    }

    static boolean isCheckBound(int pr, int pc, int nr, int nc){
        int size = Math.abs(world[pr][pc] - world[nr][nc]);
        return l <= size && size <= r;
    }
~~~

### 3. 수행 후 연합된 국가들간의 결합
연합 국가의 평균을 구하고 list로 주어진 위치의 값들을 평균값으로 변환할 수 있도록 했습니다.
~~~java
private static void setWorld(List<Loc> list) {
        int avg = tmp / list.size();
        for (Loc loc : list) {
            world[loc.r][loc.c] = avg;
        }
    }
~~~

## 소스코드
~~~java
package com.boj;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

public class BOJ_16234_인구이동 {
    static int n, l ,r;
    static int[][] world;
    static boolean[][] visited;
    static StringTokenizer st;
    static int tmp;

    static int[] dr = {1, 0, -1, 0};
    static int[] dc = {0, 1, 0, -1};

    static class Loc{
        int r;
        int c;

        public Loc(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader bf = new BufferedReader(new InputStreamReader(System.in));

        st = new StringTokenizer(bf.readLine());

        n = Integer.parseInt(st.nextToken());
        l = Integer.parseInt(st.nextToken());
        r = Integer.parseInt(st.nextToken());

        world = new int[n][n];

        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(bf.readLine());
            for (int j = 0; j < n; j++) {
                world[i][j] = Integer.parseInt(st.nextToken());
            }
        }
        int result = open();
        System.out.println(result);
    }

    static int open(){
        int result = 0;
        while(true){
            visited = new boolean[n][n];
            boolean flag = false;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if(visited[i][j]) continue;
                    List<Loc> list = bfs(i, j);
                    if(list.size()> 1){
                        setWorld(list);
                        flag = true;
                    }

                }
            }
            if(!flag) return result;
            result ++;

        }
    }

    private static void setWorld(List<Loc> list) {
        int avg = tmp / list.size();
        for (Loc loc : list) {
            world[loc.r][loc.c] = avg;
        }
    }


    static List<Loc> bfs(int r, int c){

        Queue<Loc> queue = new LinkedList<>();
        List<Loc> list = new ArrayList<>();
        queue.add(new Loc(r, c));
        list.add(new Loc(r,c));
        tmp = world[r][c];
        visited[r][c] = true;
        while (!queue.isEmpty()){
            Loc loc = queue.poll();
            int pr = loc.r;
            int pc = loc.c;

            for (int i = 0; i < 4; i++) {
                int nr = pr + dr[i];
                int nc = pc + dc[i];
                if(!isCheck(nr, nc) || visited[nr][nc] || !isCheckBound(pr, pc, nr, nc)) continue;
                visited[nr][nc] = true;
                queue.offer(new Loc(nr, nc));
                list.add(new Loc(nr, nc));
                tmp += world[nr][nc];
            }
        }
        return list;
    }

    static boolean isCheck(int nr, int nc){
        return 0<= nr && nr < n && 0 <= nc && nc < n;
    }

    static boolean isCheckBound(int pr, int pc, int nr, int nc){
        int size = Math.abs(world[pr][pc] - world[nr][nc]);
        return l <= size && size <= r;
    }


}

